B.a75=s(["Oh\u2026 that wasn\u2019t it. I get it wrong too.","Missed! Try again?","Oops! We\u2019ll get the next one."],t.s)
B.aeB=s(["{n} in a row! That\u2019s amazing!","{n}! I want to do that too!"],t.s)
B.a7W=s(["No mistakes! You\u2019ll get a good grade!"],t.s)
B.a7n=s(["Finished! Shall we do another?"],t.s)
B.acp=s(["It was hard, but we finished!"],t.s)
B.afS=s(["Listen, listen! What\u2019s that word?"],t.s)
B.aaP=s(["Your turn to speak!"],t.s)
